      setSpots(await fetchNearbySpots(region.latitude, region.longitude, radiusM, spotCategory));
    }
    setLoadError(false);
  } catch {
    setLoadError(true);   // keep the last-known pins on screen
  } finally {
    setIsLoading(false);  // always clears the spinner
  }
}, [layer, category, spotCategory]);
```
